"""Reviewed choice questions on distinct long-term financing decisions."""
import re


def chapter_nine_choices():
    rows = [
        ("债务契约与融资弹性", "企业准备签订五年期借款合同，合同限制进一步举债和分配股利。财务负责人评估这一安排，下列判断正确的是？", ["限制性条款可能约束后续融资与利润分配", "借款一经签订就不需要偿还本金", "限制性条款能保证企业永不违约", "贷款利息金额由借款人日后单方决定"], "A", "A：契约会约束后续决策。B：本金仍须按合同偿还。C：条款不能消除经营和违约风险。D：利息由合同约定。"),
        ("股票发行承销方式", "发行人与承销商协商股票发行风险的承担。若采用包销并按约定由承销商购入未售出部分，下列哪方承担该部分的销售风险？", ["承销商", "仅原有股东", "股票登记机构", "拟认购但未付款的投资者"], "A", "A：包销约定下，承销商按合同承担未售出部分的承接责任。B、C、D不因这些身份自动承担该责任。"),
        ("配股与持股比例", "上市公司向全体原股东按持股比例配股。其他股东全部认购，小股东选择不认购；除配股外没有其他股数变化。该小股东持股比例将如何变化？", ["下降", "上升", "保持不变", "必然变为零"], "A", "A：公司总股数增加而其持股数不变，比例下降。B、C忽略了新增股份；D夸大了变化。"),
        ("可转换债券稀释", "投资者依约将可转换债券转为公司新发行普通股。转换前后其他条件不变。对原股东最直接的影响是什么？", ["公司流通股数增加，原股东持股比例可能下降", "公司必须立刻以现金偿还全部转换债券本金", "普通股股数减少", "转换自动保证每股收益提高"], "A", "A：转股增加普通股数，可能稀释原持股比例。B：转换通常以发行股份代替相应债务偿付；C、D不成立。"),
        ("债券赎回条款", "某债券允许发行人在规定日期以后按约定价格提前赎回。市场利率明显下降时，该条款对发行人的主要作用是什么？", ["可能使发行人以较低利率重新融资", "迫使发行人继续按原票面利率付息至到期", "保证债券投资者获得未来利率下降的全部收益", "使发行人的借款本金自动消失"], "A", "A：若赎回及再融资的收益超过相关成本，发行人可考虑提前赎回。B与赎回权相反；C忽略再投资风险；D不成立。"),
        ("债券回售条款", "债券合同赋予投资者在特定条件下按约定价格把债券卖回发行人的权利。对该权利的描述正确的是？", ["它在约定条件下为投资者提供退出选择", "它只允许发行人单方面提前赎回", "它取消了发行人的偿付责任", "它保证投资者任何时候都能按任意价格卖回"], "A", "A：回售权属于投资者，并以合同条件为限。B描述的是赎回权；C、D扩大或颠倒了条款含义。"),
        ("债券信用利差", "固定利率债券的剩余现金流和到期日不变。因发行人信用风险上升，投资者要求的必要报酬率提高。其他条件相同时，该债券价值如何变化？", ["下降", "上升", "必然等于面值", "不受必要报酬率变化影响"], "A", "A：以更高必要报酬率折现相同现金流，现值下降。B方向相反；C、D没有成立依据。"),
        ("浮动利率债券", "浮息债券的票息定期按基准利率重新确定。假定信用利差和其他条件相同、重定价及时，与剩余期限相同的固定利率债券相比，其价格对基准利率变动通常如何？", ["敏感性较低", "敏感性必然更高", "永远完全不变", "只由票面金额决定"], "A", "A：票息重置可部分抵消利率变化对价格的影响。B方向一般不对；C忽略重置间隔与信用风险；D忽略现金流和折现率。"),
        ("债务期限与再融资风险", "企业用短期借款反复续借来支持长期项目。该策略可能带来什么风险？", ["借款到期时可能无法续借或融资成本上升", "项目现金流一定提前到达", "借款利率永远保持不变", "企业不再需要流动性管理"], "A", "A：短债长投需要反复再融资，面临续借和利率风险。B、C、D均不是该安排能够保证的结果。"),
        ("租赁与购买现金流", "公司比较租赁与购买同一设备。为保证方案可比，以下哪项做法最合适？", ["在一致的时点和税后口径下比较两方案的相关现金流现值", "只比较第一年的现金支出", "将两个方案共同发生的成本只计入购买方案", "忽略租赁期末归属和残值差异"], "A", "A：应以统一口径比较增量现金流及其时点。B忽略后续流量；C对共同成本处理不一致；D可能漏掉重要差异。"),
        ("优先股股息顺序", "假设公司发行的优先股条款约定其股息优先于普通股股利支付。公司决定分配股利时，正确的理解是什么？", ["应先按约定处理优先股股息，再考虑普通股股利", "优先股股东对任何事项都必然拥有无限投票权", "普通股股东在任何情况下都先领取约定股息", "公司不论有无可分配条件都必然支付普通股股利"], "A", "A：题设约定了分配顺序。B的投票权取决于条款与法律规定；C违背题设；D忽略分配条件。"),
        ("股权融资与控制权", "创始人持有公司60%的有表决权普通股，公司拟向外部投资者发行新股。创始人不参与认购，其他表决权安排不变。可能出现的结果是什么？", ["创始人持股和表决权比例下降", "创始人持股比例自动提高", "新增股份不会影响任何股东的比例", "创始人一定仍拥有超过半数表决权"], "A", "A：总股数增加而创始人股数不变，比例下降。B、C违背比例计算；D取决于新发行股数，不能保证。"),
    ]
    result = []
    for n, (topic, stem, options, answer, explanation) in enumerate(rows, 1):
        # Rotate correct option placement without changing its content.
        shift = (n - 1) % 4
        order = options[shift:] + options[:shift]
        correct = chr(ord("A") + order.index(options[ord(answer)-ord("A")]))
        key_map = {chr(ord("A") + i): chr(ord("A") + order.index(text)) for i, text in enumerate(options)}
        explanation = re.sub(r"[A-D]", lambda match: key_map[match.group()], explanation)
        result.append({"id": f"fm-09-choice-{n:03d}", "topic": f"长期筹资—{topic}", "stem": stem,
                       "options": [{"key": chr(ord("A") + i), "text": text} for i, text in enumerate(order)],
                       "answer": [correct], "explanation": explanation, "type": "single", "difficulty": "进阶",
                       "sourceType": "original", "source": "原创实务情境题；按讲义第9章考点设计", "year": None,
                       "page": None, "tags": [f"长期筹资—{topic}"], "authoringMethod": "manual", "decisionTask": topic})
    return result
